<template>
  <section class="security-panel">
    <header><div><h3>Bảo mật & kiểm soát</h3><p>Trạng thái quyền truy cập, riêng tư, công cụ và các cổng an toàn AI.</p></div><button :disabled="loading" @click="load"><span class="mdi mdi-refresh"/> Làm mới</button></header>
    <div v-if="error" class="state error">{{ error }}</div><div v-else-if="loading" class="state">Đang kiểm tra chính sách…</div>
    <template v-else-if="data">
