      <section class="card"><h4>Cổng bảo vệ đang áp dụng</h4><div class="safeguards"><article v-for="item in data.safeguards" :key="item.key"><span class="mdi" :class="item.status==='blocked'?'mdi-alert-circle-outline':'mdi-shield-check-outline'"/><div><strong>{{ item.label }}</strong><small>{{ status(item.status) }}</small></div><i :class="item.status"/></article></div></section>
      <div class="two-col"><section class="card"><h4>Ma trận quyền AI</h4><div class="permissions"><article v-for="item in data.permissions" :key="item.resource"><strong>{{ item.resource }}</strong><div><span v-for="action in item.actions" :key="action">{{ action }}</span></div></article></div></section><section class="card"><h4>Model và chính sách dữ liệu</h4><div class="models"><article v-for="model in data.models" :key="model.id"><div><strong>{{ model.name }}</strong><small>{{ model.provider }} · {{ model.model }}</small></div><span :class="{warn:!model.fallbackModelConfigId}">{{ model.fallbackModelConfigId?'Có fallback':'Chưa có fallback' }}</span></article><p v-if="!data.models.length">Chưa có model active hoặc approved.</p></div></section></div>
      <section class="recommend"><span class="mdi mdi-information-outline"/><div><strong>Nguyên tắc vận hành</strong><p>Chỉ mở Auto Reply sau khi có Release Production, tài liệu đã Publish, Evaluation đạt và đã quan sát đủ dữ liệu ở chế độ mô phỏng.</p></div></section>
    </template>
  </section>
</template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { api } from '@/api/index';type Data={safeguards:Array<{key:string;label:string;status:string}>;permissions:Array<{resource:string;actions:string[]}>;models:Array<{id:string;name:string;provider:string;model:string;status:string;fallbackModelConfigId:string|null}>;runtime:{autoReply:{enabled:boolean;mode:string;emergencyStop:boolean};productionReleases:number;publishedKnowledge:number;auditEventsLast30Days:number}};const data=ref<Data|null>(null),loading=ref(false),error=ref('');const status=(v:string)=>({enforced:'Đang bắt buộc',ready:'Sẵn sàng',blocked:'Chưa đạt điều kiện'} as Record<string,string>)[v]||v;async function load(){loading.value=true;error.value='';try{data.value=(await api.get<Data>('/ai/admin-center/security')).data}catch(e:any){error.value=e?.response?.data?.error||'Không thể tải trạng thái bảo mật'}finally{loading.value=false}}onMounted(load);
</script>
